29:if [ -n "$QGIS_DB_USER" ] && [ -n "$QGIS_DB_PASSWORD" ]; then
30:    echo "Creating QGIS database user: $QGIS_DB_USER"
33:        DO \$\$
35:            IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = '$QGIS_DB_USER') THEN
36:                CREATE ROLE "$QGIS_DB_USER" WITH LOGIN PASSWORD '$QGIS_DB_PASSWORD';
42:        ALTER ROLE "$QGIS_DB_USER" SET client_encoding TO 'utf8';
43:        ALTER ROLE "$QGIS_DB_USER" SET timezone TO 'Europe/Berlin';
46:        GRANT CONNECT ON DATABASE "$POSTGRES_DB" TO "$QGIS_DB_USER";
49:        GRANT USAGE ON SCHEMA public TO "$QGIS_DB_USER";
52:        GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO "$QGIS_DB_USER";
